const dateLabel = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
function importantDateElapsed(date: string, now: Date): string {
  const [year, month, day] = date.split("-").map(Number);
  const eventStart = new Date(year, month - 1, day);
  const future = eventStart.getTime() > now.getTime();
  const [start, end] = future ? [now, eventStart] : [eventStart, now];
  const elapsedHours = Math.floor((end.getTime() - start.getTime()) / 3_600_000);
  let elapsedMonths = (end.getFullYear() - start.getFullYear()) * 12 + end.getMonth() - start.getMonth();
  if (end.getDate() < start.getDate()) elapsedMonths -= 1;
  const startDay = Date.UTC(start.getFullYear(), start.getMonth(), start.getDate());
  const endDay = Date.UTC(end.getFullYear(), end.getMonth(), end.getDate());
  const elapsedDays = Math.floor((endDay - startDay) / 86_400_000);
  const elapsedYears = Math.floor(elapsedMonths / 12);
  const duration = `${elapsedYears.toLocaleString()} ${elapsedYears === 1 ? "year" : "years"} · ${elapsedMonths.toLocaleString()} ${elapsedMonths === 1 ? "month" : "months"} · ${elapsedDays.toLocaleString()} ${elapsedDays === 1 ? "day" : "days"} · ${elapsedHours.toLocaleString()} ${elapsedHours === 1 ? "hour" : "hours"}`;
  return future ? `In ${duration.toLocaleLowerCase()}` : `${duration} since`;
}
function groupByDate<T>(items: readonly T[], getDate: (item: T) => string | undefined) {
  const groups = new Map<string, T[]>();
  for (const item of items) {
    const date = getDate(item) ?? "";
    groups.set(date, [...(groups.get(date) ?? []), item]);
  }
  return [...groups.entries()]
    .sort(([dateA], [dateB]) => dateB.localeCompare(dateA))
    .map(([date, records]) => ({ date, records }));
}
type DevotionalSortOrder = "newest" | "oldest" | "title";
function sortDevotionalRecords<T>(items: readonly T[], getDate: (item: T) => string | undefined, getTitle: (item: T) => string, sortOrder: DevotionalSortOrder) {
  return [...items].sort((a, b) => sortOrder === "title"
    ? getTitle(a).localeCompare(getTitle(b))
    : (sortOrder === "newest" ? -1 : 1) * (getDate(a) ?? "").localeCompare(getDate(b) ?? ""));
}
function DevotionalRecordGroup({ title, count, expandAll, expansionRevision, children }: {
  title: string;
  count: number;
  expandAll: boolean;
  expansionRevision: number;
  children: ReactNode;
}) {
  const [expanded, setExpanded] = useState(expandAll);
  useEffect(() => setExpanded(expandAll), [expandAll, expansionRevision]);
  return <section className="devotional-date-group">
    <button type="button" className={`devotional-date-group-toggle${expanded ? " expanded" : ""}`} aria-expanded={expanded} onClick={() => setExpanded((value) => !value)}>
      <span className="devotional-date-group-title">{title}</span><span className="devotional-date-group-meta">{count} {count === 1 ? "record" : "records"}</span><ChevronRight size={15} />
    </button>
    {expanded && <div className="devotional-date-group-content">{children}</div>}
  </section>;
}
function DateGroupedRecords<T>({ items, getDate, title, groupOrder = "newest", children }: {
  items: readonly T[];
  getDate: (item: T) => string | undefined;
  title: (date: string) => string;
  groupOrder?: "newest" | "oldest";
  children: (records: T[], date: string) => ReactNode;
}) {
  const [expandAll, setExpandAll] = useState(false);
  const [expansionRevision, setExpansionRevision] = useState(0);
  const groupedRecords = groupByDate(items, getDate);
  const groups = groupOrder === "oldest" ? groupedRecords.reverse() : groupedRecords;
  function setGroupsExpanded(expanded: boolean) {
    setExpandAll(expanded);
    setExpansionRevision((revision) => revision + 1);
  }
  return <>
    <div className="record-group-actions">
      <Button type="button" size="sm" variant="outline" onClick={() => setGroupsExpanded(true)}>Show all</Button>
      <Button type="button" size="sm" variant="outline" onClick={() => setGroupsExpanded(false)}>Hide all</Button>
    </div>
    <div className="record-date-groups">{groups.map(({ date, records }, index) =>
      <DevotionalRecordGroup
        key={date || `undated-${index}`}
        title={date ? title(date) : "Date not recorded"}
        count={records.length}
        expandAll={expandAll}
        expansionRevision={expansionRevision}
      >
        {children(records, date)}
      </DevotionalRecordGroup>)}
    </div>
  </>;
}
const timeLabel = (time: string) => {
  const [hours, minutes] = time.split(":").map(Number);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes)) return time;
  return `${hours % 12 || 12}:${String(minutes).padStart(2, "0")} ${hours < 12 ? "AM" : "PM"}`;
};
const copyLabel = (value: string, maxLength: number) => `${value.replace(/ \(copy\)$/i, "").slice(0, Math.max(0, maxLength - 7))} (copy)`;
const isCookingCountUnit = (unit: string) => {
  const normalized = unit.toLocaleLowerCase().replace(/[^a-z]/g, "");
  return ["piece", "pieces", "pc", "pcs", "no", "nos", "noof", "number", "numbers", "count", "each"]
    .includes(normalized) || normalized.startsWith("noof") ||
    normalized.startsWith("numberof") || normalized.startsWith("countof");
};
const isCookingKgUnit = (unit: string) => ["kg", "kgs", "kilogram", "kilograms", "kilo", "kilos"]
  .includes(unit.trim().toLocaleLowerCase());
const roundCookingPrice = (amount: number) => Math.round((amount + Number.EPSILON) * 100) / 100;
function cookingMeasurePrice(item: CookingInventoryItem, measure: CookingStockMeasure): number | null {
  if (isCookingCountUnit(measure.unit)) {
    const kgMeasure = item.measures.find((entry) => isCookingKgUnit(entry.unit));
    if (kgMeasure) {
      return kgMeasure.unitPrice !== null && kgMeasure.unitPrice !== undefined &&
        measure.piecesPerKg !== null && measure.piecesPerKg !== undefined && measure.piecesPerKg > 0
        ? roundCookingPrice(kgMeasure.unitPrice / measure.piecesPerKg)
        : null;
    }
  }
  return measure.unitPrice;
}
function cookingPlanIngredientPrice(ingredient: CookingPlan["ingredients"][number], inventory: CookingInventoryItem[]): number | null {
  if (ingredient.inventoryItemId && ingredient.inventoryMeasureId && !ingredient.unitPriceOverride) {
    const item = inventory.find((entry) => entry.id === ingredient.inventoryItemId);
    const measure = item?.measures.find((entry) => entry.id === ingredient.inventoryMeasureId);
    if (item && measure) return cookingMeasurePrice(item, measure);
  }
  return ingredient.unitPrice;
}
const marketStateLabel = (state: string) => {
  const normalized = state.trim().toUpperCase();
  const labels: Record<string, string> = {
    REGULAR: "Open",
    PRE: "Pre-market",
    PREPRE: "Pre-market",
    POST: "After-hours",
    POSTPOST: "After-hours",
    CLOSED: "Closed",
    PROVIDER_QUOTE: "Provider quote",
    MANUAL: "Manual price",
    UNKNOWN: "Status unavailable",
    STATUS_UNAVAILABLE: "Status unavailable",
  };
  return labels[normalized] ?? (normalized ? normalized.replace(/_/g, " ").toLocaleLowerCase().replace(/^./, (letter) => letter.toLocaleUpperCase()) : "Status unavailable");
};
const monthYearLabel = (date: string) => /^\d{4}-\d{2}$/.test(date)
  ? new Date(`${date}-01T12:00:00`).toLocaleDateString(undefined, { month: "short", year: "numeric" })
  : date ? dateLabel(date) : "";
function isHttpsLink(value: string) {
  try {
    return new URL(value).protocol === "https:";
  } catch {
    return false;
  }
}
const dateAfterDays = (days: number) => {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
};

