  function saveEducationRecord(record: Omit<EducationRecord, "id">, id?: string) {
    update((previous) => {
      if (!id) return { ...previous, educationRecords: [{ ...record, id: createId() }, ...(previous.educationRecords ?? [])] };
      const current = (previous.educationRecords ?? []).find((entry) => entry.id === id);
      if (!current) return previous;
      const removedSubjects = (current.subjects ?? []).filter((entry) => !(record.subjects ?? []).some((updated) => updated.id === entry.id));
      const removedExams = (current.exams ?? []).filter((entry) => !(record.exams ?? []).some((updated) => updated.id === entry.id));
      const removedPayments = (current.payments ?? []).filter((entry) => !(record.payments ?? []).some((updated) => updated.id === entry.id));
      const removedEducationExpenses = (current.educationExpenses ?? []).filter((entry) => !(record.educationExpenses ?? []).some((updated) => updated.id === entry.id));
      const next = removedSubjects.length || removedExams.length || removedPayments.length || removedEducationExpenses.length
        ? withArchivedRecord(previous, `${current.studentName} education details`, {
          educationRecords: [{ ...current, subjects: removedSubjects, exams: removedExams, payments: removedPayments, educationExpenses: removedEducationExpenses }],
        })
        : previous;
      return {
        ...next,
        educationRecords: (previous.educationRecords ?? []).map((entry) => entry.id === id ? { ...record, id } : entry),
      };
    });
  }
  function saveStudentProfile(profile: Omit<StudentProfile, "id">, id?: string, previousName?: string) {
    const profileId = id ?? createId();
    const normalizedPreviousName = previousName?.normalize("NFKC").trim().replace(/\s+/g, " ").toLocaleLowerCase();
    update((previous) => ({
      ...previous,
      studentProfiles: (previous.studentProfiles ?? []).some((entry) => entry.id === profileId)
        ? (previous.studentProfiles ?? []).map((entry) => entry.id === profileId ? { ...profile, id: profileId } : entry)
        : [{ ...profile, id: profileId }, ...(previous.studentProfiles ?? [])],
      educationRecords: (previous.educationRecords ?? []).map((record) => {
        const isLinkedById = record.studentProfileId === profileId;
        const isLegacyMatch = !record.studentProfileId && normalizedPreviousName !== undefined &&
          record.studentName.normalize("NFKC").trim().replace(/\s+/g, " ").toLocaleLowerCase() === normalizedPreviousName;
        return isLinkedById || isLegacyMatch
          ? { ...record, studentProfileId: profileId, studentName: profile.name }
          : record;
      }),
    }));
  }
